/**
 * Matchup tips (server only): read from the DB while valid (2 months),
 * otherwise generated by Gemini, validated and stored. A×B and B×A share one
 * row (alphabetical pair); the columns come back in the order asked.
 */

import 'server-only';
import { prisma } from '@/src/lib/db';
import { AppError } from '@/src/lib/errors';
import {
  MATCHUP_TTL_DAYS,
  orderPair,
  orientRows,
  type MatchupRow,
} from '@/src/lib/matchup';
import { championList } from '@/src/services/dataDragonService';
import { generateMatchupRows } from '@/src/services/geminiService';

export type Matchup = {
  rows: MatchupRow[];
  /** When the AI wrote it */
  createdAt: string;
  /** Read from the DB (true) or just generated (false) */
  cached: boolean;
};

const DAY = 86_400_000;

/**
 * `first`/`second`: champion ids (Riot's championName). `beforeGenerate` runs
 * only when the AI will be called (per-user limit: cache hits are free).
 */
export async function getMatchup(
  first: string,
  second: string,
  beforeGenerate: () => Promise<void> = async () => {}
): Promise<Matchup> {
  if (first === second) {
    throw new AppError('Escolha dois campeões diferentes', 400);
  }
  const known = new Set((await championList()).map((c) => c.id));
  for (const id of [first, second]) {
    if (!known.has(id)) throw new AppError(`Campeão desconhecido: ${id}`, 400);
  }

  const { champA, champB, swapped } = orderPair(first, second);
  const stored = await prisma.matchupTip.findUnique({
    where: { champA_champB: { champA, champB } },
  });
  if (stored && stored.expiresAt > new Date()) {
    return {
      rows: orientRows(stored.rows as MatchupRow[], swapped),
      createdAt: stored.createdAt.toISOString(),
      cached: true,
    };
  }

  await beforeGenerate();
  const rows = await generateMatchupRows(champA, champB);
  const now = new Date();
  const data = {
    rows,
    createdAt: now,
    expiresAt: new Date(now.getTime() + MATCHUP_TTL_DAYS * DAY),
  };
  await prisma.matchupTip.upsert({
    where: { champA_champB: { champA, champB } },
    create: { champA, champB, ...data },
    update: data,
  });
  return {
    rows: orientRows(rows, swapped),
    createdAt: now.toISOString(),
    cached: false,
  };
}
